                target: sampleUrl,
                remediation: "Implement strict server-side object ownership verification against the authenticated caller tenant ID.",
                reproCurl: `curl -i -s -X ${ep.method} "${sampleUrl}" -H "Authorization: ${context.secondAuthToken}"`,
